questions.text:
¿Cuál será la salida del siguiente código?

for (let i = 1; i <= 7; i += 2) {
    console.log(i);
}

¿Cuál será la salida del siguiente código?

for (let i = 10; i >= 4; i -= 2) {
    console.log(i);
}

¿Qué se mostrará en consola al ejecutar el siguiente código?

let numero = 14;

if (numero % 2 !== 0) {
    console.log("A");
} else if (numero > 10) {
    console.log("B");
} else {
    console.log("C");
}

¿Qué imprime el siguiente código?

let edad = 18;

if (edad >= 18) {
    console.log("Mayor de edad");
} else {
    console.log("Menor de edad");
}

¿Cuál será la salida del siguiente código?

let numero = 7;

if (numero > 10) {
    console.log("A");
} else {
    console.log("B");
}

¿Qué muestra la consola al ejecutar el siguiente código?

let nota = 8;

if (nota >= 7) {
    console.log("Aprobado");
} else {
    console.log("Reprobado");
}

¿Cuál será la salida del siguiente código?

let nota = 6;

if (nota >= 9) {
    console.log("Excelente");
} else if (nota >= 7) {
    console.log("Aprobado");
} else {
    console.log("Reprobado");
}

¿Qué imprime el siguiente programa?

let temperatura = 25;

if (temperatura > 30) {
    console.log("Calor");
} else if (temperatura >= 20) {
    console.log("Templado");
} else {
    console.log("Frío");
}

¿Qué mostrará la consola?

let numero = 0;

if (numero > 0) {
    console.log("Positivo");
} else if (numero < 0) {
    console.log("Negativo");
} else {
    console.log("Cero");
}

¿Cuál será la salida del siguiente código?

let edad = 15;

if (edad >= 18) {
    console.log("Adulto");
} else if (edad >= 13) {
    console.log("Adolescente");
} else {
    console.log("Niño");
}

¿Cuál es el valor almacenado en la variable resultado después de ejecutar el código?

function calcular(a, b) {
    return a * 2 + b;
}

let resultado = calcular(4, 3);
console.log(resultado);

En la siguiente función, ¿cuáles son los parámetros?

function sumar(a, b) {
    return a + b;
}

¿Qué valor queda almacenado en la variable total después de ejecutar el código?

function calcularDescuento(precio, descuento) {
    return precio - (precio * descuento / 100);
}

let total = calcularDescuento(200, 10);
console.log(total);

¿Cuál es la salida del siguiente código?

function sumar(a, b) {
    return a + b;
}

let resultado = sumar(4, 6);
console.log(resultado);

¿Qué imprime el siguiente código?

function doble(numero) {
    return numero * 2;
}

console.log(doble(5));

¿Cuál es la salida del siguiente código?

for (let i = 1; i <= 3; i++) {
    console.log(i);
}

¿Cuántas veces se ejecuta el siguiente ciclo?

for (let i = 0; i < 5; i++) {
    console.log("Hola");
}

¿Cuál es la salida del siguiente código?

for (let i = 2; i <= 6; i += 2) {
    console.log(i);
}

¿Cuál es la salida del siguiente código?

for (let i = 3; i > 0; i--) {
    console.log(i);
}

¿Cuál es la salida del siguiente código?

let numeros = [10, 20, 30, 40];

console.log(numeros[2]);

¿Qué imprime el siguiente código?

let colores = ["rojo", "azul", "verde"];

console.log(colores.length);

¿Qué valor queda almacenado en la variable resultado?

let estudiante = {
    nombre: "Carlos",
    curso: "Programación",
    nota: 9
};

let resultado = estudiante.nota;
console.log(resultado);

¿Cuál es el valor de producto.precio después de ejecutar el código?

let producto = {
    nombre: "Laptop",
    precio: 850,
    disponible: true
};

producto.precio = producto.precio + 100;

console.log(producto.precio);
